import { test, expect } from '@playwright/test';

test.describe('Polling behavior on page navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should start polling when the page is loaded', async ({ page }) => {
    // Assuming there's a button to start polling
    await page.getByRole('button', { name: /start polling/i }).click();

    // Check if polling has started (e.g., a loading indicator appears)
    const loadingIndicator = page.getByText(/loading/i);
    await expect(loadingIndicator).toBeVisible();
  });

  test('should stop polling when navigating away from the page', async ({ page }) => {
    await page.getByRole('button', { name: /start polling/i }).click();
    const loadingIndicator = page.getByText(/loading/i);
    await expect(loadingIndicator).toBeVisible();

    // Navigate away from the page
    await page.getByRole('link', { name: /go to another page/i }).click(); // Replace with actual link text

    // Verify that polling has stopped (e.g., loading indicator disappears)
    await expect(loadingIndicator).toBeHidden();
  });
});
